import 'dotenv/config'; // Keep this if you rely on it for local testing setup

/**
 * Defines the structure and required keys for the application configuration.
 */
const REQUIRED_VARS = [
  'DATABASE_URL', 
  'REDIS_URL', 
  'STRIPE_SECRET_KEY', 
  'STRIPE_WEBHOOK_SECRET',
  'JWT_SECRET', 
  'SESSION_SECRET',
  'AWS_ACCESS_KEY_ID', 
  'AWS_SECRET_ACCESS_KEY',
];

/**
 * Validates that all necessary environment variables are present.
 * @throws {Error} If any required environment variable is missing.
 */
function validateEnv() {
  const missing = REQUIRED_VARS.filter((k) => !process.env[k]);
  if (missing.length > 0) {
    throw new Error(`Configuration Error: Missing required environment variables: ${missing.join(', ')}`);
  }
}

